select @ngay_ct1 as ngay_ct1, @ngay_ct2 as ngay_ct2, @ngay_hd1 as ngay_hd1, @ngay_hd2 as ngay_hd2
exec zrpt_kehoachxuatcont_bee @ngay_ct1, @ngay_ct2, @ngay_hd1, @ngay_hd2, @ma_kh, @ky1, @nam1, @ky2, @nam2, '@@sysDatabaseName', @@language, @@userID, @@admin

			
		
		
	

	
		
			&OutlineEntry;
			&JavascriptReportFilter;
			&ScriptQueryFilterString; 
			
function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete); 
	
}
function close$VoucherFilter$(f) {
	try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}
}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var ngay_ct1 = f.getItemValue('ngay_ct1'), ngay_ct2 = f.getItemValue('ngay_ct2'), ky1 = f.getItemValue('ky1'), nam1 = f.getItemValue('nam1'), ky2 = f.getItemValue('ky2'), nam2 = f.getItemValue('nam2');
			var msg = ((f._language == 'v') ? 'Từ kỳ/năm và Đến kỳ/năm phải nằm trong khoảng ngày từ/đến Lịch xuất.' : 'Period/year from and Period/year to must be in range of Date from/to.');
	
			if (ky1 || nam1 || ky2 || nam2) {
				if (nam1 < ngay_ct1.getFullYear() || nam2 > ngay_ct2.getFullYear() ) {
					$message.show(msg, String.format('$find(\'{0}\')', f.get_id()));
					f._checked = false;
					break;
				}
			}
			var g = f.grid
			g._hiddenForms = [];
			g._alterTitle = [null, [['%s1', f.getItem('ngay_ct1').value, true], ['%s2', f.getItem('ngay_ct2').value, true]]];
g._queryFilterString = getQueryFilterString(f, 'ngay_ct1, ngay_ct2');
			//remove$GridReport$Filter(g);
			break;
		default:
			break;
	}
}
function onChange$Filter$ngay_ct(o, type) {
	var f = o.parentForm;
	f.setItemValue('ex_nam' + type, o._controlBehavior._selectedDate.getFullYear());
}
function onChange$Filter$nam(o, type) {
	var f = o.parentForm;
	f.setItemValue('nam' + type, f.getItemValue('ex_nam' + type));
}


		
	

